<script>const rows=document.getElementById('rows');document.getElementById('add').onclick=()=>rows.append(rows.firstElementChild.cloneNode(true));rows.addEventListener('change',e=>{if(e.target.name==='product_id[]')e.target.closest('.item-row').querySelector('[name="unit_price[]"]').value=e.target.selectedOptions[0].dataset.price||0});rows.addEventListener('click',e=>{if(e.target.classList.contains('remove')&&rows.children.length>1)e.target.closest('.item-row').remove()});</script>
